"""Sort semantic version strings by SemVer 2.0.0 precedence."""


def _identifier_key(identifier):
    """Key for one pre-release identifier.

    Numeric identifiers compare as integers and sort below alphanumeric ones,
    which compare in ASCII order.
    """
    if identifier.isascii() and identifier.isdigit():
        return (0, int(identifier), "")
    return (1, 0, identifier)


def _version_key(version):
    """Return a sort key implementing SemVer precedence.

    Build metadata (after '+') is ignored. The first hyphen separates the
    pre-release from the core, because the core never contains a hyphen.
    """
    without_build = version.split("+", 1)[0]
    core, sep, pre = without_build.partition("-")
    major, minor, patch = (int(part) for part in core.split("."))

    if sep:
        # A pre-release sorts below the same version without one.
        pre_key = (0, tuple(_identifier_key(i) for i in pre.split(".")))
    else:
        pre_key = (1,)

    # Tuple comparison gives the rule that a shorter identifier list is lower
    # when all shared identifiers are equal.
    return (major, minor, patch, pre_key)


def sort_versions(vs):
    """Return the versions sorted lowest precedence first.

    Python's sorted() is stable, so versions that tie keep their input order.
    """
    return sorted(vs, key=_version_key)
